(3091437, 434708, 66515, '<td valign="top">Very powerful image. This mosaic in Strawberry Fields has been photographed numerous times before. Each day new things find there way to this monument to John Lennon. I like this: Simple with a clear message. Well done. (I only hope others get the significance). 8</td>', 'Very powerful image. This mosaic in Strawberry Fields has been photographed numerous times before. Each day new things find there way to this monument to John Lennon. I like this: Simple with a clear message. Well done. (I only hope others get the significance). 8', '2006-12-06 03:00:13.000000', NULL, 1),
(3091438, 435191, 66515, '<td valign="top">You definitely got a chuckle out of me. Very creative and well executed. 7</td>', 'You definitely got a chuckle out of me. Very creative and well executed. 7', '2006-12-06 03:00:15.000000', NULL, 1),
(3091439, 434120, 68985, '<td valign="top">amazing image. it works great in BW!</td>', 'amazing image. it works great in BW!', '2006-12-06 03:00:17.000000', NULL, 1),
(3091442, 432985, 66515, '<td valign="top">Doesn''t really feel related to the challenge to me. Not saying that fire can''t be related to death. Just not in this way.</td>', 'Doesn''t really feel related to the challenge to me. Not saying that fire can''t be related to death. Just not in this way.', '2006-12-06 03:01:43.000000', NULL, 1),
