(3091445, 435117, 66515, '<td valign="top">Really well done. Unfortunately the lights in the background are a little blurry which distracts from the shot.</td>', 'Really well done. Unfortunately the lights in the background are a little blurry which distracts from the shot.', '2006-12-06 03:02:25.000000', NULL, 1),
(3091446, 433689, 66515, '<td valign="top">Really like the B&amp;W conversion here. A little stark but thats part of its appeal I think.</td>', 'Really like the B&W conversion here. A little stark but thats part of its appeal I think.', '2006-12-06 03:03:13.000000', NULL, 1),
(3091447, 434985, 66515, '<td valign="top">If I recall correctly no one actually dies in fight club. Sorry...DNMC</td>', 'If I recall correctly no one actually dies in fight club. Sorry...DNMC', '2006-12-06 03:03:49.000000', NULL, 1),
(3091451, 435203, 66515, '<td valign="top">Creative and somewhat comical look at the challenge. The sepia tones work well with the subject. 7</td>', 'Creative and somewhat comical look at the challenge. The sepia tones work well with the subject. 7', '2006-12-06 03:04:22.000000', NULL, 1),
(3091453, 434767, 66515, '<td valign="top">I like the idea and it really is a hard one to execute. Getting the person to pose correctly, look sad AND reflect tombstones? Kinda tough. I would like to see more detail in the reflection but that might be asking a little much. 7</td>', 'I like the idea and it really is a hard one to execute. Getting the person to pose correctly, look sad AND reflect tombstones? Kinda tough. I would like to see more detail in the reflection but that might be asking a little much. 7', '2006-12-06 03:05:47.000000', NULL, 1),
(3091454, 434859, 66515, '<td valign="top">This looks like the catwalk to a professional wrestling match. Doesn''t really sell me on how it fits the challenge. Sorry :(</td>', 'This looks like the catwalk to a professional wrestling match. Doesn''t really sell me on how it fits the challenge. Sorry :(', '2006-12-06 03:06:24.000000', NULL, 1),
(3091456, 434163, 66515, '<td valign="top">I am not sure what to think here. On the one hand, there''s a lot of overexposure going on. On the other hand it really seems to work here. It gives the shot a sort of ephemeral feel to it. 7</td>', 'I am not sure what to think here. On the one hand, there''s a lot of overexposure going on. On the other hand it really seems to work here. It gives the shot a sort of ephemeral feel to it. 7', '2006-12-06 03:07:48.000000', NULL, 1),
