(3097170, 434883, 40679, '<td valign="top">maybe it''s more interesting to shoot an image like that in the fields or something like that, now it''s more like a snapshot in the street where you live.</td>', 'maybe it''s more interesting to shoot an image like that in the fields or something like that, now it''s more like a snapshot in the street where you live.', '2006-12-07 15:54:41.000000', NULL, 1),
(3097172, 435179, 40679, '<td valign="top">looks more like a fast unedited snapshot to me. not a lot contrast or interesting colors, the ship is centred, horizon tilted, all these things you could''ve edited in PS or another program.</td>', 'looks more like a fast unedited snapshot to me. not a lot contrast or interesting colors, the ship is centred, horizon tilted, all these things you could''ve edited in PS or another program.', '2006-12-07 15:55:49.000000', NULL, 1),
(3097173, 434531, 40679, '<td valign="top">hmm if they treat my organs like this, I''d rather not ;)</td>', 'hmm if they treat my organs like this, I''d rather not ;)', '2006-12-07 15:56:15.000000', NULL, 1),
