(3097176, 434493, 28532, '<td valign="top">Sweet!! Excellent shot - nicely done - especially like the reflection in the cleaver!!</td>', 'Sweet!! Excellent shot - nicely done - especially like the reflection in the cleaver!!', '2006-12-07 15:57:00.000000', NULL, 1),
