(3099231, 434336, 62187, '<td valign="top">Don''t do it man...you''re a great photographer or at least you know one! Trophy shot...(no pun intended)...10</td>', 'Don''t do it man...you''re a great photographer or at least you know one! Trophy shot...(no pun intended)...10', '2006-12-08 07:10:46.000000', NULL, 1),
(3099235, 435136, 62187, '<td valign="top">Hari Kari - thanks for the language lesson. Great photo but I don''t see any ''act'' going on. Still...8</td>', 'Hari Kari - thanks for the language lesson. Great photo but I don''t see any ''act'' going on. Still...8', '2006-12-08 07:12:48.000000', NULL, 1),
