(3099691, 434665, 40679, '<td valign="top">I can understand this was a harsh photo to take, but a little zooming would be nice. the image also looks flat, some contrast could help you with that.</td>', 'I can understand this was a harsh photo to take, but a little zooming would be nice. the image also looks flat, some contrast could help you with that.', '2006-12-08 11:39:57.000000', NULL, 1),
(3099696, 435165, 40679, '<td valign="top">natural framing works most of the time, but this is a bit too blurry for me to like it. the colors and sharpness at the stone looks nice</td>', 'natural framing works most of the time, but this is a bit too blurry for me to like it. the colors and sharpness at the stone looks nice', '2006-12-08 11:41:05.000000', NULL, 1),
(3099700, 433176, 40679, '<td valign="top">this is a bit too much of a snapshot for me. maybe better if you got a bit closer to the tree, shoot from the front part of the tree. colors are a bit flat, some contrast could work here.</td>', 'this is a bit too much of a snapshot for me. maybe better if you got a bit closer to the tree, shoot from the front part of the tree. colors are a bit flat, some contrast could work here.', '2006-12-08 11:42:18.000000', NULL, 1),
(3099708, 435319, 40679, '<td valign="top">hmm you have to give the flowers water, you know ;) I like the way the curtain touches the fowers but the b/w looks a bit flat and the setting is a bit messy with the blinds at the back. might be cool with a black background, but keep the curtains.</td>', 'hmm you have to give the flowers water, you know ;) I like the way the curtain touches the fowers but the b/w looks a bit flat and the setting is a bit messy with the blinds at the back. might be cool with a black background, but keep the curtains.', '2006-12-08 11:44:57.000000', NULL, 1),
(3099712, 434859, 40679, '<td valign="top">the photo is a bit too small to check the details good enough, but I can see it''s a bit flat at the bottom part and the man. what''s he doing there anyway?</td>', 'the photo is a bit too small to check the details good enough, but I can see it''s a bit flat at the bottom part and the man. what''s he doing there anyway?', '2006-12-08 11:45:58.000000', NULL, 1),
