(3101878, 434869, 68769, '<td valign="top">Not really death, but WOW what a photograph</td>', 'Not really death, but WOW what a photograph', '2006-12-09 08:01:59.000000', NULL, 1),
(3101958, 435009, 61191, '<td valign="top">Wow, this is excellent! Superb lighting and atmosphere. One of the best shots so far.</td>', 'Wow, this is excellent! Superb lighting and atmosphere. One of the best shots so far.', '2006-12-09 09:12:01.000000', NULL, 1),
(3102004, 433861, 42256, '<td valign="top">Nice colors in the bokeh! ... I wish the angel had more light though and the cross was a little more straight.. nice shot though!</td>', 'Nice colors in the bokeh! ... I wish the angel had more light though and the cross was a little more straight.. nice shot though!', '2006-12-09 10:12:35.000000', NULL, 1),
(3102006, 433026, 42256, '<td valign="top">deadly!! a little scary as well .. rated this shot in the night but decided to comment on this one during day time to avoid bad dreams! nice shot!</td>', 'deadly!! a little scary as well .. rated this shot in the night but decided to comment on this one during day time to avoid bad dreams! nice shot!', '2006-12-09 10:13:44.000000', NULL, 1),
(3102008, 434120, 54728, '<td valign="top">Very gloomy.  I love the mist.  Good composition.</td>', 'Very gloomy.  I love the mist.  Good composition.', '2006-12-09 10:14:17.000000', NULL, 1),
(3102011, 435292, 42256, '<td valign="top">the angel here is underexposed, would have loved to really see the glowing white, but than the great blue of the sky would have washed .. maybe a gradual density filter would have helped.. still a nice composition!</td>', 'the angel here is underexposed, would have loved to really see the glowing white, but than the great blue of the sky would have washed .. maybe a gradual density filter would have helped.. still a nice composition!', '2006-12-09 10:15:14.000000', NULL, 1),
(3102012, 435320, 42256, '<td valign="top">Great use of shallow DOF.. love the colors of the shot. .very dead but yet beautiful! bumping this up!</td>', 'Great use of shallow DOF.. love the colors of the shot. .very dead but yet beautiful! bumping this up!', '2006-12-09 10:15:46.000000', NULL, 1),
(3102014, 435239, 54728, '<td valign="top">Too out of focus.  Only the belt is in focus, while the spoon and needle and watch are all out of focus.  Detracts from the picture.</td>', 'Too out of focus.  Only the belt is in focus, while the spoon and needle and watch are all out of focus.  Detracts from the picture.', '2006-12-09 10:16:05.000000', NULL, 1),
(3102019, 434637, 54728, '<td valign="top">Interesting.  I like the light shining from the right.  The crop is perhaps a little too close.  But overall I like your photo.</td>', 'Interesting.  I like the light shining from the right.  The crop is perhaps a little too close.  But overall I like your photo.', '2006-12-09 10:17:28.000000', NULL, 1),
(3102020, 435195, 42256, '<td valign="top">imo if the man was sitting where he has his leg up on the grave , this shot would have been more expressive.. also I guess its not of much help in basic editing but in advanced editing dodging the grave stone would have really made this shot stand out! Great attempt though!</td>', 'imo if the man was sitting where he has his leg up on the grave , this shot would have been more expressive.. also I guess its not of much help in basic editing but in advanced editing dodging the grave stone would have really made this shot stand out! Great attempt though!', '2006-12-09 10:17:55.000000', NULL, 1),
(3102028, 434882, 54728, '<td valign="top">I like the idea.  But the presentation is not very impressive.  A closer crop would have worked better (maybe less leaves to allow for it).  I think the lighting is a little off took, as it adds all these white highlights to the leaves, instead of just letting us see the colours.  So, to resume: great idea, but to improve, you could use less leaves (maybe 5), separate them and zoom in closer, fix lighting.</td>', 'I like the idea.  But the presentation is not very impressive.  A closer crop would have worked better (maybe less leaves to allow for it).  I think the lighting is a little off took, as it adds all these white highlights to the leaves, instead of just letting us see the colours.  So, to resume: great idea, but to improve, you could use less leaves (maybe 5), separate them and zoom in closer, fix lighting.', '2006-12-09 10:22:41.000000', NULL, 1),
(3102031, 433954, 41277, '<td valign="top">right choice - black and white</td>', 'right choice - black and white', '2006-12-09 10:29:12.000000', NULL, 1),
(3102038, 434526, 54728, '<td valign="top">Wow, impressive!  The crop is a little too close on top.  But strong image.</td>', 'Wow, impressive!  The crop is a little too close on top.  But strong image.', '2006-12-09 10:41:34.000000', NULL, 1),
(3102075, 435241, 18367, '<td valign="top">This is indeed a beautiful image, but I am having problems associating this with Death.</td>', 'This is indeed a beautiful image, but I am having problems associating this with Death.', '2006-12-09 11:17:29.000000', NULL, 1),
(3102099, 434493, 39825, '<td valign="top">*ggg* cool. I think this one is my favourite! 10 for it.</td>', '*ggg* cool. I think this one is my favourite! 10 for it.', '2006-12-09 11:36:36.000000', NULL, 1),
(3102112, 434542, 28532, '<td valign="top">Love the way the red stands out against the sepia tones!  Kinda spooky....  I also like the softness - it helps exaggerate the eerie feel - Nicely done.</td>', 'Love the way the red stands out against the sepia tones!  Kinda spooky....  I also like the softness - it helps exaggerate the eerie feel - Nicely done.', '2006-12-09 11:45:05.000000', NULL, 1),
(3102116, 434679, 28532, '<td valign="top">Sweet - the clouds are wonderful - I like the overal feel to the shot.  Nicely done!</td>', 'Sweet - the clouds are wonderful - I like the overal feel to the shot.  Nicely done!', '2006-12-09 11:47:27.000000', NULL, 1),
(3102117, 435203, 28532, '<td valign="top">Love it!!  Great angle and the sepia works very well.  Nicely done!</td>', 'Love it!!  Great angle and the sepia works very well.  Nicely done!', '2006-12-09 11:47:41.000000', NULL, 1),
(3102179, 434810, 67301, '<td valign="top">great idea, and such an effort to get this shot with basic editing.. I am impressed. bump up to 7</td>', 'great idea, and such an effort to get this shot with basic editing.. I am impressed. bump up to 7', '2006-12-09 12:24:32.000000', NULL, 1),
(3102182, 434882, 49943, '<td valign="top">Nice perspective...could have been shot better with the older ones fading out ... but great perspective...couldnt have struck me</td>', 'Nice perspective...could have been shot better with the older ones fading out ... but great perspective...couldnt have struck me', '2006-12-09 12:27:14.000000', NULL, 1),
