(3102309, 435182, 69585, '<td valign="top">great shot!!</td>', 'great shot!!', '2006-12-09 13:31:01.000000', NULL, 1),
(3102310, 433861, 69585, '<td valign="top">beautiful shot!!</td>', 'beautiful shot!!', '2006-12-09 13:31:43.000000', NULL, 1),
