(3102713, 435324, 38924, '<td valign="top">I like the sepia tone.  Focus is a little soft, however.</td>', 'I like the sepia tone.  Focus is a little soft, however.', '2006-12-09 17:46:36.000000', NULL, 1),
(3102721, 433432, 38924, '<td valign="top">Would''ve like to have seen more of the skull.</td>', 'Would''ve like to have seen more of the skull.', '2006-12-09 17:49:14.000000', NULL, 1),
(3102836, 433861, 16402, '<td valign="top">I really like the color in this and the little bit of ivy is a nice touch whether it was naturally there or added. I think it might have had a bit more impact with me if the cross had been straigher vertically. Nice job. 7</td>', 'I really like the color in this and the little bit of ivy is a nice touch whether it was naturally there or added. I think it might have had a bit more impact with me if the cross had been straigher vertically. Nice job. 7', '2006-12-09 19:00:54.000000', NULL, 1),
(3102841, 434425, 16402, '<td valign="top">Lovely shot and while it or could say lots of things, "death" doesn''t come across to me.</td>', 'Lovely shot and while it or could say lots of things, "death" doesn''t come across to me.', '2006-12-09 19:03:46.000000', NULL, 1),
(3102845, 434213, 16402, '<td valign="top">The flare spots are a bit distracting but this is still a really cool image that works for me. Good Job. 7</td>', 'The flare spots are a bit distracting but this is still a really cool image that works for me. Good Job. 7', '2006-12-09 19:07:37.000000', NULL, 1),
(3102847, 434512, 16402, '<td valign="top">If the skull was a bit more toward the center of the image, so the entire shadow was inside the frame, this would be just about perfect for me. 8</td>', 'If the skull was a bit more toward the center of the image, so the entire shadow was inside the frame, this would be just about perfect for me. 8', '2006-12-09 19:09:42.000000', NULL, 1),
(3102850, 434993, 16402, '<td valign="top">IMHO you should have gotten lots closer to the subject, the markers and flowers. As it is there''s too much unnecessary information (the road and trees). Good effort though.</td>', 'IMHO you should have gotten lots closer to the subject, the markers and flowers. As it is there''s too much unnecessary information (the road and trees). Good effort though.', '2006-12-09 19:12:01.000000', NULL, 1),
(3102851, 434731, 16402, '<td valign="top">Great ghost image. Nice composition and toning.</td>', 'Great ghost image. Nice composition and toning.', '2006-12-09 19:12:40.000000', NULL, 1),
